  const errors = [];
  const warnings = [];
  const name = path.basename(skillDir);
  const skillMdPath = path.join(skillDir, 'SKILL.md');

  if (!fs.existsSync(skillMdPath)) {
    return { errors: ['SKILL.md is missing'], warnings };
  }
  const text = fs.readFileSync(skillMdPath, 'utf8');
  const meta = parseFrontmatter(text);

  if (!meta) errors.push('SKILL.md is missing YAML frontmatter (--- name/description ---)');
  else {
    if (!meta.name) errors.push('Frontmatter is missing "name"');
    else {
      if (!/^[a-z0-9-]+$/.test(meta.name)) errors.push(`Invalid name "${meta.name}": use lowercase letters, digits, and hyphens only`);
      if (meta.name.length >= 64) errors.push(`Name "${meta.name}" must be under 64 characters`);
      if (meta.name !== name) errors.push(`Frontmatter name "${meta.name}" does not match folder name "${name}"`);
    }
    if (!meta.description) errors.push('Frontmatter is missing "description"');
    else {
      if (meta.description.length < 40) warnings.push('Description is short; include what the skill does AND when to use it');
      if (/TODO/i.test(meta.description)) errors.push('Description contains a TODO placeholder');
    }
  }

  const body = text.replace(/^---[\s\S]*?---/, '');
  if (/TODO/i.test(body)) errors.push('SKILL.md body contains TODO placeholders');

  // Check local markdown links point to existing files.
  const linkRe = /\]\(([^)#]+)\)/g;
  let m;
  while ((m = linkRe.exec(text))) {
    const target = m[1];
    if (/^(https?:|#)/.test(target)) continue;
