  const outFile = path.join(outDir, `${name}.skill`);
  fs.writeFileSync(outFile, zip);

  const names = verifyZip(zip, files.map((f) => f.name));
  console.log(`Validation passed: ${errors.length} errors, ${warnings.length} warnings.`);
  console.log(`Packaged ${names.length} file(s): ${names.join(', ')}`);
  console.log(`Created ${outFile} (${zip.length} bytes).`);
