  'conversations.members',
  'conversations.replies',
  'files.info',
  'reactions.get',
  'reactions.list',
  'search.messages',
  'team.info',
  'users.info',
  'users.list',
  'users.lookupByEmail',
]);

const ARRAY_KEY = {
  'conversations.list': 'channels',
  'conversations.history': 'messages',
  'conversations.replies': 'messages',
  'conversations.members': 'members',
  'users.list': 'members',
  'reactions.list': 'items',
};

function usage() {
  console.log(`Usage:
  node slack_api.cjs <method> [paramsJson] [options]

Examples:
  node slack_api.cjs auth.test
  node slack_api.cjs chat.postMessage '{"channel":"#general","text":"hi"}'
  node slack_api.cjs conversations.history '{"channel":"C123","limit":20}' --all

Options:
  --token TOKEN      Slack token (overrides SLACK_BOT_TOKEN/SLACK_USER_TOKEN/SLACK_TOKEN)
  --all              Follow cursor pagination and merge result arrays
  --max-items N      Truncate arrays longer than N in output (default 500, 0 = unlimited)
  --pretty           Pretty-print JSON output
  --help             Show this help`);
}

function parseArgs(argv) {
  const opts = { token: null, all: false, maxItems: 500, pretty: false, help: false };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--token') {
      opts.token = argv[++i];
    } else if (a === '--all') {
      opts.all = true;
    } else if (a === '--pretty') {
      opts.pretty = true;
    } else if (a === '--help') {
      opts.help = true;
    } else if (a === '--max-items') {
      const n = parseInt(argv[++i], 10);
      opts.maxItems = Number.isNaN(n) ? 500 : n;
    } else if (a.startsWith('--')) {
      console.error(`Unknown option: ${a}`);
      process.exit(2);
    } else {
      positional.push(a);
    }
  }
  opts.method = positional[0] || null;
  try {
    opts.params = positional[1] ? JSON.parse(positional[1]) : {};
  } catch (e) {
    console.error(`Invalid params JSON: ${e.message}`);
    process.exit(2);
  }
  return opts;
}

async function request(method, params, token) {
  const headers = { Authorization: `Bearer ${token}` };
  let url = BASE_URL + method;
  const init = { headers };
  if (GET_SAFE.has(method)) {
    const qs = new URLSearchParams(params).toString();
    if (qs) url += '?' + qs;
  } else {
    init.method = 'POST';
    init.headers['Content-Type'] = 'application/json; charset=utf-8';
    init.body = JSON.stringify(params);
  }
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(url, init);
    if (res.status === 429 && attempt < MAX_RETRIES) {
      const secs = parseInt(res.headers.get('retry-after') || '1', 10) || 1;
      await new Promise((r) => setTimeout(r, secs * 1000));
      continue;
    }
    return res
      .json()
      .catch(() => ({ ok: false, error: `HTTP ${res.status} (non-JSON response)` }));
  }
}

function truncateArrays(value, maxItems) {
  if (!maxItems) return value;
  const notes = [];
  const walk = (v, path) => {
    if (Array.isArray(v)) {
      if (v.length > maxItems) {
        notes.push(`${path || '<root>'} (${v.length} items, showing ${maxItems})`);
        return v.slice(0, maxItems);
      }
      return v.map((item, i) => walk(item, `${path}[${i}]`));
    }
    if (v && typeof v === 'object') {
      const out = {};
      for (const [k, val] of Object.entries(v)) {
        out[k] = walk(val, path ? `${path}.${k}` : k);
      }
      return out;
    }
    return v;
  };
  const out = walk(value, '');
  if (notes.length) out._truncated = notes;
  return out;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.help || !opts.method) {
    usage();
    process.exit(opts.help ? 0 : 2);
  }

  const token = opts.token || TOKEN_ENVS.map((e) => process.env[e]).find(Boolean);
  if (!token) {
    console.error(
      'No Slack token found. Pass --token TOKEN or set SLACK_BOT_TOKEN / SLACK_USER_TOKEN / SLACK_TOKEN.'
    );
    process.exit(2);
  }

  let data = await request(opts.method, opts.params, token);
  if (!data.ok) {
    console.error(
      `Slack API error (${opts.method}): ${data.error}${data.needed ? ` (needed scope: ${data.needed})` : ''}`
    );
    process.exit(1);
  }

  const key = ARRAY_KEY[opts.method];
  if (opts.all && key && Array.isArray(data[key])) {
    const all = data[key].slice();
    let pages = 1;
    let cursor = data.response_metadata && data.response_metadata.next_cursor;
    while (cursor && pages < MAX_PAGES) {
      const page = await request(opts.method, { ...opts.params, cursor }, token);
      if (!page.ok) {
        console.error(`Slack API error (${opts.method}): ${page.error}`);
        process.exit(1);
      }
      if (Array.isArray(page[key])) all.push(...page[key]);
      cursor = page.response_metadata && page.response_metadata.next_cursor;
      pages++;
    }
    if (cursor) data._note = `Pagination stopped after ${MAX_PAGES} pages; more results may exist.`;
    data[key] = all;
    delete data.response_metadata;
  }

  console.log(JSON.stringify(truncateArrays(data, opts.maxItems), null, opts.pretty ? 2 : 0));
}

main().catch((e) => {
  console.error(`Request failed: ${e.message}`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * package_skill.js — validate a skill directory and package it into a
 * distributable .skill file (a zip archive, STORE method, no compression).
 * No external dependencies.
 *
 * Usage:
 *   node package_skill.js <skill-dir> [out-dir]
 *
 * Exit codes: 0 success, 1 validation failure or packaging error.
 */
'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

function parseFrontmatter(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const meta = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = line.match(/^([A-Za-z0-9_-]+):\s*(.*)$/);
    if (kv) meta[kv[1]] = kv[2].replace(/^['"]|['"]$/g, '');
  }
  return meta;
}

function validate(skillDir) {
  const errors = [];
  const warnings = [];
  const name = path.basename(skillDir);
  const skillMdPath = path.join(skillDir, 'SKILL.md');

  if (!fs.existsSync(skillMdPath)) {
    return { errors: ['SKILL.md is missing'], warnings };
  }
  const text = fs.readFileSync(skillMdPath, 'utf8');
  const meta = parseFrontmatter(text);

  if (!meta) errors.push('SKILL.md is missing YAML frontmatter (--- name/description ---)');
  else {
    if (!meta.name) errors.push('Frontmatter is missing "name"');
    else {
      if (!/^[a-z0-9-]+$/.test(meta.name)) errors.push(`Invalid name "${meta.name}": use lowercase letters, digits, and hyphens only`);
      if (meta.name.length >= 64) errors.push(`Name "${meta.name}" must be under 64 characters`);
      if (meta.name !== name) errors.push(`Frontmatter name "${meta.name}" does not match folder name "${name}"`);
    }
    if (!meta.description) errors.push('Frontmatter is missing "description"');
    else {
      if (meta.description.length < 40) warnings.push('Description is short; include what the skill does AND when to use it');
      if (/TODO/i.test(meta.description)) errors.push('Description contains a TODO placeholder');
    }
  }

  const body = text.replace(/^---[\s\S]*?---/, '');
  if (/TODO/i.test(body)) errors.push('SKILL.md body contains TODO placeholders');

  // Check local markdown links point to existing files.
  const linkRe = /\]\(([^)#]+)\)/g;
  let m;
  while ((m = linkRe.exec(text))) {
    const target = m[1];
    if (/^(https?:|#)/.test(target)) continue;
    const full = path.join(skillDir, target);
    if (!fs.existsSync(full)) errors.push(`Referenced file not found: ${target}`);
  }

  return { errors, warnings };
}

// ---------------------------------------------------------------------------
// Minimal ZIP writer (STORE method)
// ---------------------------------------------------------------------------

function crc32(buf) {
  let table = crc32.table;
  if (!table) {
    table = crc32.table = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c;
    }
  }
  let crc = -1;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ table[(crc ^ buf[i]) & 0xff];
  return (crc ^ -1) >>> 0;
}

function dosDateTime(d = new Date()) {
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
  const date = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time, date };
}

function buildZip(files) {
  const chunks = [];
  const central = [];
  let offset = 0;
  const { time, date } = dosDateTime();

  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf8');
    const crc = crc32(f.data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4);         // version needed
    local.writeUInt16LE(0, 6);          // flags
    local.writeUInt16LE(0, 8);          // method: store
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(f.data.length, 18); // compressed size
    local.writeUInt32LE(f.data.length, 22); // uncompressed size
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28); // extra length
    chunks.push(local, nameBuf, f.data);

    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0); // central directory signature
    cd.writeUInt16LE(20, 4);         // version made by
    cd.writeUInt16LE(20, 6);         // version needed
    cd.writeUInt16LE(0, 8);          // flags
    cd.writeUInt16LE(0, 10);         // method: store
    cd.writeUInt16LE(time, 12);
    cd.writeUInt16LE(date, 14);
    cd.writeUInt32LE(crc, 16);
    cd.writeUInt32LE(f.data.length, 20);
    cd.writeUInt32LE(f.data.length, 24);
    cd.writeUInt16LE(nameBuf.length, 28);
    cd.writeUInt16LE(0, 30); // extra length
    cd.writeUInt16LE(0, 32); // comment length
    cd.writeUInt16LE(0, 34); // disk number start
    cd.writeUInt16LE(0, 36); // internal attrs
    cd.writeUInt32LE(0, 38); // external attrs
    cd.writeUInt32LE(offset, 42);
    central.push(cd, nameBuf);

    offset += local.length + nameBuf.length + f.data.length;
  }

  const cdSize = central.reduce((n, b) => n + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(files.length, 8);
  eocd.writeUInt16LE(files.length, 10);
  eocd.writeUInt32LE(cdSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...chunks, ...central, eocd]);
}

function verifyZip(buf, expectedNames) {
  if (buf.length < 22) throw new Error('file too small to be a zip');
  const eocd = buf.subarray(buf.length - 22);
  if (eocd.readUInt32LE(0) !== 0x06054b50) throw new Error('EOCD signature not found');
  const count = eocd.readUInt16LE(10);
  const cdOffset = eocd.readUInt32LE(16);
  if (count !== expectedNames.length) throw new Error(`entry count mismatch: ${count} != ${expectedNames.length}`);

  const names = [];
  let pos = cdOffset;
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(pos) !== 0x02014b50) throw new Error(`central directory entry ${i} has bad signature`);
    const nameLen = buf.readUInt16LE(pos + 28);
    const name = buf.subarray(pos + 46, pos + 46 + nameLen).toString('utf8');
    names.push(name);
    pos += 46 + nameLen;
  }
  const missing = expectedNames.filter((n) => !names.includes(n));
  if (missing.length) throw new Error(`missing entries: ${missing.join(', ')}`);
  return names;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function listFiles(dir, base = '') {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = base ? `${base}/${entry.name}` : entry.name;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...listFiles(full, rel));
    else out.push({ name: rel, full });
  }
  return out;
}

function main() {
  const skillDir = path.resolve(process.argv[2] || '.');
  const outDir = path.resolve(process.argv[3] || '.');
  const name = path.basename(skillDir);

  if (!fs.existsSync(skillDir)) {
    console.error(`Skill directory not found: ${skillDir}`);
    process.exit(1);
  }

  const { errors, warnings } = validate(skillDir);
  for (const w of warnings) console.log(`Warning: ${w}`);
  if (errors.length) {
    for (const e of errors) console.error(`Validation error: ${e}`);
    console.error(`Validation failed for "${name}" — no package created.`);
    process.exit(1);
  }

  fs.mkdirSync(outDir, { recursive: true });
  const files = listFiles(skillDir).map((f) => ({ name: f.name, data: fs.readFileSync(f.full) }));
  const zip = buildZip(files);
  const outFile = path.join(outDir, `${name}.skill`);
  fs.writeFileSync(outFile, zip);

  const names = verifyZip(zip, files.map((f) => f.name));
  console.log(`Validation passed: ${errors.length} errors, ${warnings.length} warnings.`);
  console.log(`Packaged ${names.length} file(s): ${names.join(', ')}`);
  console.log(`Created ${outFile} (${zip.length} bytes).`);
}

main();
